"use client";

import React, {
  useState,
  useMemo,
  useCallback,
  useEffect,
  useRef,
} from "react";

import axios from "axios";
import { useParams, useRouter } from "next/navigation";

import { useAuth } from "@/hooks/useSanctumAuth";
import { IMAGE_TYPE, getImageUrl, onImageError } from "@/utils/utils";

import styles from "./ItemDetailView.module.css";

/* ============================
   型定義
============================ */
interface ApiUser {
  id: number;
  name: string;
  user_image: string | null;
}

interface Item {
  id: number;
  user_id: number;
  name: string;
  brand: string | null;
  price: number | null;
  item_image: string | null;
  remain: number;
  explain: string;
  category: string;
  condition: string | null;
}

interface Comment {
  id: number;
  user: ApiUser;
  comment: string;
  created_at: string;
}

interface ItemDetailResponse {
  item: Item;
  is_favorited: boolean;
  favorites_count: number;
  comments: Comment[];
  errors?: string[];
}

/* ============================
   メインコンポーネント
============================ */

export default function ItemDetailPage() {
  const params = useParams();
  const router = useRouter();

  const {
    user,
    apiClient,
    isAuthenticated,
    isLoading: authLoading,
  } = useAuth();

  /* ---------- state ---------- */
  const [item, setItem] = useState<Item | null>(null);
  const [comments, setComments] = useState<Comment[]>([]);
  const [isFavorited, setIsFavorited] = useState(false);
  const [favoritesCount, setFavoritesCount] = useState(0);

  const [error, setError] = useState("");
  const [itemErrors, setItemErrors] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [newComment, setNewComment] = useState("");
  const [commentErrors, setCommentErrors] = useState<string[]>([]);
  const [isSubmittingComment, setIsSubmittingComment] = useState(false);

  const commentAbortControllerRef = useRef<AbortController | null>(null);
  const hasFetchedRef = useRef(false);

  /* ---------- itemId ---------- */
const itemId = useMemo(() => {
  const raw = params.items_id;

  if (!raw) return null;

  const idString = Array.isArray(raw) ? raw[0] : raw;

  if (!idString) return null;

  const parsed = Number(idString);
  return Number.isNaN(parsed) ? null : parsed;
}, [params.items_id]);

  /* ---------- computed ---------- */
  const isOwner = isAuthenticated && user?.id === item?.user_id;
  const canInteract = isAuthenticated && !isOwner;
  const isSoldOut = (item?.remain ?? 0) < 1;

  const itemCategories = useMemo(() => {
    if (!item?.category) return [];
    try {
      const parsed = JSON.parse(item.category);
      return Array.isArray(parsed) ? parsed : [item.category];
    } catch {
      return [item.category];
    }
  }, [item]);

  const fullItemImageUrl = useMemo(() => {
    const img = item?.item_image ?? null; // undefined → null
    return getImageUrl(img, IMAGE_TYPE.ITEM, 0);
  }, [item?.item_image]);

  /* ============================
     API: Fetch Item Detail
============================ */
  const fetchItem = useCallback(
    async (id: number) => {
      setIsLoading(true);
      setError("");
      setItemErrors([]);

      try {
        let data: ItemDetailResponse;

        if (isAuthenticated && apiClient) {
          const res = await apiClient.get(`/item/${id}`);
          data = res.data;
        } else {
          const res = await axios.get(
            `${process.env.NEXT_PUBLIC_API_BASE_URL}/api/item/${id}`,
          );
          data = res.data;
        }

        if (!data.item) {
          setError("商品情報が取得できませんでした。");
          return;
        }

        setItem(data.item);
        setIsFavorited(data.is_favorited);
        setFavoritesCount(data.favorites_count);
        setComments(data.comments);
      } catch (e) {
        console.error(e);
        setError("商品情報の取得に失敗しました。");
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, isAuthenticated],
  );

  /* ============================
     Effect: Load Item
============================ */
  useEffect(() => {
    if (!itemId) {
      setError("商品IDが不正です");
      setIsLoading(false);
      return;
    }
    if (authLoading) return;

    if (hasFetchedRef.current) return;
    hasFetchedRef.current = true;

    fetchItem(itemId);
  }, [itemId, authLoading, fetchItem]);

  /* ============================
     Favorite
============================ */
  const submitFavorite = async () => {
    if (!item) return;
    if (!isAuthenticated) {
      router.push("/login");
      return;
    }
    if (isOwner) {
      setItemErrors(["ご自身の商品です。"]);
      return;
    }

    const before = isFavorited;
    setIsFavorited(!before);
    setFavoritesCount((p) => (before ? p - 1 : p + 1));

    try {
      await apiClient?.request({
        method: before ? "DELETE" : "POST",
        url: `/items/${item.id}/favorite`,
      });
    } catch {
      setIsFavorited(before);
      setFavoritesCount((p) => (before ? p + 1 : p - 1));
    }
  };

  /* ============================
     Comment
============================ */
  const submitComment = async () => {
    if (!isAuthenticated) {
      router.push("/login");
      return;
    }
    if (!item) return;
    if (!newComment.trim()) {
      setCommentErrors(["コメントを入力してください"]);
      return;
    }

    if (commentAbortControllerRef.current) {
      commentAbortControllerRef.current.abort();
    }
    const controller = new AbortController();
    commentAbortControllerRef.current = controller;

    setIsSubmittingComment(true);
    setCommentErrors([]);

    try {
      const res = await apiClient?.post(
        "/comment",
        { item_id: item.id, comment: newComment },
        { signal: controller.signal },
      );

      const posted = res?.data.comment;
      if (posted) {
        setComments((prev) => [
          ...prev,
          {
            id: posted.id,
            comment: posted.comment,
            created_at: posted.created_at,
            user: posted.user ?? {
              id: user!.id,
              name: user!.name,
              user_image: user!.user_image || null,
            },
          },
        ]);
        setNewComment("");
      }
    } catch (e: any) {
      if (e.code !== "ERR_CANCELED") {
        setCommentErrors(["コメント投稿に失敗しました"]);
      }
    } finally {
      setIsSubmittingComment(false);
      commentAbortControllerRef.current = null;
    }
  };

  /* ============================
     Navigation
============================ */
  const navigateToPurchase = () => {
    if (isOwner) return router.push("/mypage");
    if (isAuthenticated && item) return router.push(`/purchase/${item.id}`);
    return router.push("/login");
  };

  const loading = isLoading || authLoading;

  /* ============================
     Render
============================ */
  if (loading) {
    return (
      <div className="text-center mt-20">
        <p>読み込み中...</p>
      </div>
    );
  }

  if (error || itemErrors.length > 0) {
    return (
      <div className="text-center mt-20 text-red-500">
        <p>{error}</p>
        {itemErrors.map((e, idx) => (
          <p key={idx}>{e}</p>
        ))}
      </div>
    );
  }

  if (!item) {
    return (
      <div className="text-center mt-20 text-gray-500">
        商品が見つかりませんでした
      </div>
    );
  }

  /* ============================
     Main View
============================ */
  return (
    <div className={styles.itemDetailWrapper}>
      <div className={styles.itemDetailContents}>
        <div className={styles.card}>
          {/* 画像 */}
          <div className={styles.imageArea}>
            <img
              src={fullItemImageUrl}
              className={styles.mainImage}
              onError={(e) => onImageError(e, item.name)}
            />
          </div>

          {/* 情報 */}
          <div className={styles.infoArea}>
            <h2 className={styles.itemName}>{item.name}</h2>

            <p className={styles.itemBrandValue}>{item.brand ?? "未登録"}</p>

            <div className={styles.priceBox}>
              {isSoldOut ? (
                <span className={styles.priceSoldOut}>SOLD OUT</span>
              ) : (
                <span className={styles.priceValue}>
                  ¥{item.price?.toLocaleString()}
                </span>
              )}
            </div>

            {/* お気に入り */}
            <button
              onClick={submitFavorite}
              className={styles.favoriteButton}
              disabled={!canInteract}
            >
              {isFavorited ? "❤️" : "🤍"} {favoritesCount}
            </button>

            {/* 購入 */}
            <button
              onClick={navigateToPurchase}
              className={styles.purchaseButton}
            >
              {isOwner
                ? "マイページへ"
                : isSoldOut
                  ? "SOLD OUT"
                  : isAuthenticated
                    ? "カートへ"
                    : "ログインして購入"}
            </button>

            {/* 説明 */}
            <div className={styles.explainBox}>
              <p>{item.explain}</p>
            </div>

            {/* カテゴリ */}
            <div className={styles.categoryBox}>
              {itemCategories.map((c, i) => (
                <span key={i} className={styles.categoryTag}>
                  {c}
                </span>
              ))}
            </div>

            {/* コメント */}
            <div className={styles.commentHistory}>
              {comments.map((c) => (
                <div key={c.id} className={styles.commentItem}>
                  <strong>{c.user.name}</strong>
                  <p>{c.comment}</p>
                </div>
              ))}
            </div>

            {/* コメント投稿 */}
            {isAuthenticated ? (
              <div className={styles.commentForm}>
                <textarea
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  className={styles.commentTextarea}
                />
                <button
                  onClick={submitComment}
                  disabled={isSubmittingComment}
                  className={styles.commentButton}
                >
                  投稿する
                </button>
                {commentErrors.map((err, idx) => (
                  <p key={idx} className="text-red-500 text-sm">
                    {err}
                  </p>
                ))}
              </div>
            ) : (
              <p className="text-center text-red-500 mt-4">
                ログインしてコメントする
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
